/**
 * Pull the real Coursera catalog so training recommendations can be
 * grounded in courses that actually exist.
 *
 * Why: lib/training-catalog.ts was generated by asking a model for course
 * URLs. Sampling found 73% of specific course links dead on verifiable
 * hosts, and ~3,151 records carried an invented price. This replaces
 * "what the model recalled" with "what the provider publishes".
 *
 * Public endpoint, no auth. Writes data/coursera-catalog.json.
 */
import fs from "node:fs";
import path from "node:path";

const API = "https://api.coursera.org/api/courses.v1";
const FIELDS = "slug,name,description,workload,primaryLanguages";
const PAGE = 100;
const OUT = path.join(process.cwd(), "data", "coursera-catalog.json");

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function getPage(start, attempt = 0) {
  const url = `${API}?start=${start}&limit=${PAGE}&fields=${FIELDS}`;
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(30000) });
    if (res.status === 429 || res.status >= 500) throw new Error(`http ${res.status}`);
    if (!res.ok) throw new Error(`http ${res.status}`);
    return await res.json();
  } catch (e) {
    if (attempt >= 4) throw e;
    await sleep(1500 * Math.pow(2, attempt)); // back off on rate limit
    return getPage(start, attempt + 1);
  }
}

const first = await getPage(0);
const total = first?.paging?.total ?? 0;
console.log(`Coursera reports ${total} courses`);

const byslug = new Map();
const add = (els) => {
  for (const e of els || []) {
    if (e.slug) byslug.set(e.slug, {
      slug: e.slug, name: e.name,
      workload: e.workload || null,
      description: (e.description || "").slice(0, 400),
    });
  }
};
add(first.elements);

let start = PAGE;
while (start < total) {
  const d = await getPage(start);
  add(d.elements);
  start += PAGE;
  if (start % 2000 === 0) console.log(`  ${byslug.size} collected...`);
  await sleep(120); // be polite
}

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, JSON.stringify({
  fetchedAt: new Date().toISOString(),
  source: "https://api.coursera.org/api/courses.v1",
  count: byslug.size,
  courses: Array.from(byslug.values()),
}, null, 0));
console.log(`WROTE ${byslug.size} real courses -> ${OUT}`);
